<?php
require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$adminTitle='Paket Voting';$eventId=(int)($_GET['event']??(active_event()['id']??0));$id=(int)($_GET['edit']??0);$edit=null;if($id){$s=db()->prepare('SELECT * FROM vote_packages WHERE id=?');$s->execute([$id]);$edit=$s->fetch();}
if(is_post()){try{verify_csrf();$pid=(int)($_POST['id']??0);$data=['event_id'=>(int)$_POST['event_id'],'name'=>trim((string)$_POST['name']),'amount'=>(int)$_POST['amount'],'base_points'=>(int)$_POST['base_points'],'bonus_points'=>(int)$_POST['bonus_points'],'total_points'=>(int)$_POST['base_points']+(int)$_POST['bonus_points'],'badge'=>trim((string)$_POST['badge']),'sort_order'=>(int)$_POST['sort_order'],'is_active'=>isset($_POST['is_active'])?1:0];if($data['amount']<10000||$data['base_points']<1)throw new RuntimeException('Nominal minimal Rp10.000 dan poin harus valid.');if($pid){$stmt=db()->prepare('UPDATE vote_packages SET event_id=?,name=?,amount=?,base_points=?,bonus_points=?,total_points=?,badge=?,sort_order=?,is_active=?,updated_at=NOW() WHERE id=?');$stmt->execute(array_merge(array_values($data),[$pid]));audit('UPDATE_PACKAGE','vote_packages',$pid,null,$data);}else{$stmt=db()->prepare('INSERT INTO vote_packages(event_id,name,amount,base_points,bonus_points,total_points,badge,sort_order,is_active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,NOW(),NOW())');$stmt->execute(array_values($data));$pid=(int)db()->lastInsertId();audit('CREATE_PACKAGE','vote_packages',$pid,null,$data);}flash('success','Paket voting disimpan.');redirect('admin/packages.php?event='.$data['event_id']);}catch(Throwable $e){flash('danger',$e->getMessage());}}
$events=db()->query('SELECT id,name,year FROM events ORDER BY year DESC')->fetchAll();$stmt=db()->prepare('SELECT * FROM vote_packages WHERE event_id=? ORDER BY sort_order,amount');$stmt->execute([$eventId]);$rows=$stmt->fetchAll();require __DIR__.'/partials/header.php';
?>
<div class="row g-4"><div class="col-xl-4"><div class="admin-card p-4"><h5><?= $edit?'Edit':'Tambah' ?> Paket</h5><form method="post" class="row g-3 mt-1"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="col-12"><label class="form-label">Event</label><select class="form-select" name="event_id"><?php foreach($events as $ev):?><option value="<?= (int)$ev['id'] ?>" <?= ($edit['event_id']??$eventId)==$ev['id']?'selected':'' ?>><?= e($ev['year'].' - '.$ev['name']) ?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Nama Paket</label><input class="form-control" name="name" required value="<?= e($edit['name']??'Paket Dukungan') ?>"></div><div class="col-12"><label class="form-label">Nominal Pembayaran</label><input class="form-control" type="number" step="1000" min="10000" name="amount" required value="<?= e($edit['amount']??10000) ?>"></div><div class="col-6"><label class="form-label">Poin Dasar</label><input class="form-control" type="number" name="base_points" required value="<?= e($edit['base_points']??10000) ?>"></div><div class="col-6"><label class="form-label">Bonus Poin</label><input class="form-control" type="number" name="bonus_points" value="<?= e($edit['bonus_points']??0) ?>"></div><div class="col-8"><label class="form-label">Label/Badge</label><input class="form-control" name="badge" value="<?= e($edit['badge']??'') ?>" placeholder="Paling Populer"></div><div class="col-4"><label class="form-label">Urutan</label><input class="form-control" type="number" name="sort_order" value="<?= e($edit['sort_order']??0) ?>"></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_active" <?= !isset($edit['is_active'])||$edit['is_active']?'checked':'' ?>><label class="form-check-label">Paket aktif</label></div></div><div class="col-12 d-grid"><button class="btn btn-admin">Simpan Paket</button></div><?php if($edit):?><div class="col-12 d-grid"><a class="btn btn-light" href="packages.php?event=<?= $eventId ?>">Batal</a></div><?php endif;?></form></div></div><div class="col-xl-8"><div class="admin-card overflow-hidden"><div class="p-4 d-flex justify-content-between align-items-center"><h5 class="mb-0">Daftar Paket</h5><form><select class="form-select" name="event" onchange="this.form.submit()"><?php foreach($events as $ev):?><option value="<?= (int)$ev['id'] ?>" <?= $eventId===$ev['id']?'selected':'' ?>><?= e($ev['year']) ?></option><?php endforeach;?></select></form></div><div class="table-responsive"><table class="table table-admin"><thead><tr><th>Paket</th><th>Nominal</th><th>Poin Dasar</th><th>Bonus</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?= e($r['name']) ?></strong><?php if($r['badge']):?><small class="d-block text-warning"><?= e($r['badge']) ?></small><?php endif;?></td><td><?= rupiah($r['amount']) ?></td><td><?= number_format((int)$r['base_points'],0,',','.') ?></td><td><?= number_format((int)$r['bonus_points'],0,',','.') ?></td><td class="fw-bold text-success"><?= number_format((int)$r['total_points'],0,',','.') ?></td><td><?= $r['is_active']?'Aktif':'Nonaktif' ?></td><td><a class="btn btn-sm btn-outline-success" href="?event=<?= $eventId ?>&edit=<?= (int)$r['id'] ?>"><i class="bi bi-pencil"></i></a></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require __DIR__.'/partials/footer.php';?>
